const { withDangerousMod } = require("expo/config-plugins");
const fs = require("node:fs/promises");
const path = require("node:path");

/**
 * RevenueCat deliberately terminates iOS Release builds configured with its
 * Test Store key. EAS preview therefore uses Debug, but Expo's generated Xcode
 * phase normally skips embedding JavaScript in Debug and expects Metro.
 *
 * Only the preview profile sets FORCE_BUNDLING=1. During prebuild this plugin
 * writes Xcode's local environment hook, undoing SKIP_BUNDLING so the resulting
 * internal build is both Debug (safe for Test Store) and standalone.
 *
 * The bundle must also be built with `--dev false`, because `react-native-xcode.sh`
 * derives `DEV` from the Xcode configuration alone and would otherwise embed a
 * dev bundle. A dev bundle assumes Metro is reachable: `expo/src/async-require/
 * messageSocket` opens a devtools socket at module scope under `__DEV__` and
 * throws "Cannot create devtools websocket connections in embedded environments"
 * the moment it finds the bundle was not served, killing the app before the
 * runtime is ready. `EXTRA_PACKAGER_ARGS` is appended after the script's own
 * `--dev $DEV`, and Expo CLI resolves repeated flags last-wins.
 *
 * `--minify false` mirrors what the same script does for Hermes release builds;
 * Hermes bytecode does not benefit from minification. Note that `__DEV__` is
 * then false here, so the Test Store key is selected via
 * EXPO_PUBLIC_MOTIF_REVENUECAT_ALLOW_TEST_STORE, which the preview profile sets.
 */
module.exports = function withStandaloneDebugBundle(config) {
  return withDangerousMod(config, [
    "ios",
    async (modConfig) => {
      if (process.env.FORCE_BUNDLING !== "1") return modConfig;

      const environmentPath = path.join(
        modConfig.modRequest.platformProjectRoot,
        ".xcode.env.local",
      );
      await fs.writeFile(
        environmentPath,
        [
          "# Generated by with-standalone-debug-bundle for EAS preview.",
          "unset SKIP_BUNDLING",
          "export SKIP_BUNDLING_METRO_IP=1",
          'export EXTRA_PACKAGER_ARGS="--dev false --minify false"',
          "",
        ].join("\n"),
      );
      return modConfig;
    },
  ]);
};
